CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS registry_categories (id text PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', enabled boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS registry_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id text NOT NULL REFERENCES registry_categories(id), name text NOT NULL, base_url text NOT NULL, registry_host text NOT NULL, provider text NOT NULL DEFAULT '', region text NOT NULL DEFAULT '', tags jsonb NOT NULL DEFAULT '[]', is_enabled boolean NOT NULL DEFAULT false, probe_mode text NOT NULL DEFAULT 'registry', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS probe_results (id bigserial PRIMARY KEY, source_id uuid NOT NULL REFERENCES registry_sources(id), status text NOT NULL, dns_duration_ms bigint NOT NULL DEFAULT 0, tcp_duration_ms bigint NOT NULL DEFAULT 0, tls_duration_ms bigint NOT NULL DEFAULT 0, registry_duration_ms bigint NOT NULL DEFAULT 0, error text NOT NULL DEFAULT '', checked_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS probe_results_source_checked_idx ON probe_results(source_id, checked_at DESC);
